vector<Point> LineCrossCircle(Point a,Point b,Point o,double r){
	// 直线与圆的交点
	vector<Point> ret;
	Point t = ShadowPOnLine(o,a,b); // o到直线|ab|的垂足
	Vec ot = PtoV(o,t);
	if(VecMod(ot)-r>eps)return ret; // 没有交点
	if(fabs(VecMod(ot)-r)<eps){ // 如果相切
		ret.push_back(t);
