	}
	double lr = sqrt(r*r-VecMod2(ot));
	Vec ta = t + VecUnit(PtoV(t,a))*lr , tb = t + VecUnit(PtoV(t,b))*lr;
	ret.push_back(ta);
	ret.push_back(tb);
	return ret;	
}

