bool POnSeg(Point p, Point a, Point b){
	// 点在线段上
	if(fabs(xMult(PtoV(a,b), PtoV(a,p))) > eps)return false;
	if(min(a.x,b.x) > p.x || p.x > max(a.x,b.x))return false;
	if(min(a.y,b.y) > p.y || p.y > max(a.y,b.y))return false;
	return true;
}


